/* Blog pages (generated by tools/blog/build.mjs): fills in the read counts and makes "Copy link" copy.
 *
 * Read counts: every [data-reads-path] on the page (the byline, the front page, "Keep reading") is filled
 * from the API's GET /api/blog/reads in one request, so the count is never in the committed HTML. A page
 * with fewer than five readers says "New" rather than look empty; "0 reads" is never shown; if the API
 * cannot be reached the slot stays invisible (it keeps its room, so nothing moves either way).
 * [data-reads-format="compact"] writes thousands as "2.3k reads" where space is tight; the byline writes
 * "1,234 reads".
 *
 * The page view that makes a read is recorded by assets/track.js, which every generated page loads. */
(function (root) {
  "use strict";

  /** Below this many readers a page shows "New". */
  var NEW_BELOW = 5;

  /** "1 read", "12 reads", "1,234 reads"; compact: "2.3k reads", "12.3k reads", "1.2m reads". */
  function formatReads(n, compact) {
    n = Math.max(0, Math.floor(n));
    var word = n === 1 ? " read" : " reads";
    if (compact && n >= 1000) {
      var big = n >= 1e6, v = n / (big ? 1e6 : 1e3);
      // Rounded down to one decimal (to a whole number from 100k), so a count is never overstated.
      var s = v >= 100 ? String(Math.floor(v)) : (Math.floor(v * 10) / 10).toFixed(1).replace(/\.0$/, "");
      return s + (big ? "m" : "k") + " reads";
    }
    return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",") + word;
  }

  /** What a slot shows for a count: "New" under five readers, the count from there; null to leave it hidden. */
  function readsLabel(n, compact) {
    if (typeof n !== "number" || !isFinite(n) || n < 0) return null;
    return n < NEW_BELOW ? "New" : formatReads(n, compact);
  }

  /** The path as the API keys it (and track.js records it): lowercase, no trailing slash. */
  function normalisePath(p) {
    return String(p || "").split(/[?#]/)[0].toLowerCase().replace(/\/index\.html$/, "").replace(/\/+$/, "");
  }

  if (typeof module === "object" && module.exports) {
    module.exports = { formatReads: formatReads, readsLabel: readsLabel, normalisePath: normalisePath, NEW_BELOW: NEW_BELOW };
    return;
  }

  var doc = root.document;
  var API = root.location.hostname === "localhost" || root.location.hostname === "127.0.0.1"
    ? "http://localhost:5080"
    : "https://api.notefusion.studio";

  function fillReads() {
    var slots = Array.prototype.slice.call(doc.querySelectorAll("[data-reads-path]"));
    if (!slots.length || !root.fetch) return;
    var paths = [];
    slots.forEach(function (el) {
      var p = normalisePath(el.getAttribute("data-reads-path"));
      if (p && paths.indexOf(p) < 0) paths.push(p);
    });
    paths = paths.slice(0, 50);
    var ctl = root.AbortController ? new AbortController() : null;
    var timer = ctl ? setTimeout(function () { ctl.abort(); }, 8000) : null;
    root.fetch(API + "/api/blog/reads?paths=" + encodeURIComponent(paths.join(",")), {
      mode: "cors", credentials: "omit", signal: ctl ? ctl.signal : undefined
    }).then(function (r) { return r.ok ? r.json() : null; }).then(function (counts) {
      if (timer) clearTimeout(timer);
      if (!counts || typeof counts !== "object") return;
      slots.forEach(function (el) {
        var label = readsLabel(counts[normalisePath(el.getAttribute("data-reads-path"))], el.getAttribute("data-reads-format") === "compact");
        if (!label) return;
        el.textContent = label;
        el.removeAttribute("aria-hidden");
        el.classList.add("is-ready");
      });
    }).catch(function () { /* the count is a nicety: stay hidden */ });
  }

  function wireCopyLinks() {
    doc.querySelectorAll("[data-copy-link]").forEach(function (a) {
      a.addEventListener("click", function (e) {
        if (!root.navigator.clipboard || !root.isSecureContext) return; // the link itself still works
        e.preventDefault();
        var label = a.textContent;
        root.navigator.clipboard.writeText(a.href).then(function () {
          a.textContent = "Link copied";
          setTimeout(function () { a.textContent = label; }, 2000);
        }, function () { root.location.href = a.href; });
      });
    });
  }

  fillReads();
  wireCopyLinks();
})(typeof window !== "undefined" ? window : this);
